{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Estazolam, the closest analogue by Morgan similarity (0.27), has an absolute oral bioavailability of 87% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alprazolam, a structurally related triazolobenzodiazepine with a chlorophenyl group, has an absolute oral bioavailability of 0.84 in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Clobazam is rapidly and extensively absorbed with 87–100% oral bioavailability, and food does not affect its absorption, directly supporting high F under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vorozole, which shares the chiral azole–chlorophenyl motif with the query, has excellent oral bioavailability in postmenopausal women, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Tenidap, a chlorophenyl-containing heteroaromatic drug, has an absolute oral bioavailability of 85% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Loxapine has a systemic availability of 0.29 in humans; although this is the lowest among close analogues, it remains above the 20% threshold and therefore supports a high prediction at this cutoff.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Adinazolam has an absolute oral bioavailability of 39% in healthy volunteers; despite first-pass metabolism, this is still above the 20% threshold and supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "One bupropion record reports 10% oral bioavailability, which would be contradictory, but bupropion is structurally distant and other bupropion records report >80% F; this outlier does not outweigh the analogue consensus.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most structurally related analogues, including the closest match estazolam and the azole–chlorophenyl analogue vorozole, show oral bioavailability well above 20%; even the lower-end analogues (loxapine 29%, adinazolam 39%) remain above the threshold. The only sub-20% record (bupropion 10%) is an outlier from a structurally distant molecule and is contradicted by other bupropion data. Therefore the query is predicted to have high absolute oral bioavailability at the F≥20% cutoff.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities are low (0.20–0.27), limiting structural transferability.",
    "Fed-state effect on the query is not directly tested; only clobazam data indicate food does not affect absorption.",
    "Conflicting bupropion bioavailability records create minor uncertainty, though bupropion is structurally distant."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

